  id: number;
  title: string;
  genre: string;
  runtimeMinutes: number;
  format: 'PL dubbing' | 'PL subtitles';
}

export interface Screening {
  id: number;
  movieId: number;
  date: string;
  time: string;
  occupiedSeats: string[];
}

import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Movie, Screening } from './models';

const BASE_URL = 'http://localhost:3000';

@Injectable({ providedIn: 'root' })
export class CinemaApi {
  private readonly http = inject(HttpClient);

  getMovies(): Promise<Movie[]> {
    return firstValueFrom(this.http.get<Movie[]>(`${BASE_URL}/movies`));
  }

  getScreeningsOn(date: string): Promise<Screening[]> {
    return firstValueFrom(this.http.get<Screening[]>(`${BASE_URL}/screenings`, { params: { date } }));
  }
}

const ISO_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;

export const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

/** Formats a date as `YYYY-MM-DD` in the browser's local time zone. */
export function toIsoDate(date: Date): string {
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${date.getFullYear()}-${month}-${day}`;
}

/** Parses a `YYYY-MM-DD` string into a local date, or returns `null` if it is not a real calendar date. */
export function parseIsoDate(value: string | null | undefined): Date | null {
  const match = value ? ISO_DATE.exec(value) : null;
  if (!match) {
    return null;
  }
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const date = new Date(year, month - 1, day);
  const valid = date.getFullYear() === year && date.getMonth() === month - 1 && date.getDate() === day;
  return valid ? date : null;
}

import { Component, computed, inject, input, resource } from '@angular/core';
import { MatButtonModule } from '@angular/material/button';
import { MatDatepickerModule } from '@angular/material/datepicker';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { Router } from '@angular/router';
import { CinemaApi } from '../cinema-api';
import { parseIsoDate, toIsoDate, WEEKDAYS } from '../dates';
import { Movie, Screening } from '../models';

interface MovieCard {
  movie: Movie;
  screenings: Screening[];
}

const now = new Date();
const today = toIsoDate(now);

@Component({
  selector: 'app-movie-list',
  imports: [MatButtonModule, MatDatepickerModule, MatFormFieldModule, MatInputModule],
  templateUrl: './movie-list.html',
  styleUrl: './movie-list.scss',
})
export class MovieList {
  private readonly api = inject(CinemaApi);
  private readonly router = inject(Router);

  /** Bound from the `date` query parameter. */
  readonly date = input<string>();

  protected readonly minDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());

  protected readonly dayButtons = Array.from({ length: 5 }, (_, offset) => {
    const day = new Date(now.getFullYear(), now.getMonth(), now.getDate() + offset);
    return { iso: toIsoDate(day), label: offset === 0 ? 'Today' : WEEKDAYS[day.getDay()] };
  });

  /** The requested date when it is valid and not in the past; otherwise today. */
  protected readonly selectedDate = computed(() => {
    const requested = this.date();
    const valid = parseIsoDate(requested) !== null && requested! >= today;
    return valid ? requested! : today;
  });

  /** The datepicker shows the selected day only when no day button represents it. */
  protected readonly pickerValue = computed(() => {
    const selected = this.selectedDate();
    return this.dayButtons.some((day) => day.iso === selected) ? null : parseIsoDate(selected);
  });

  protected readonly cards = resource({
    params: () => this.selectedDate(),
    loader: async ({ params: date }): Promise<MovieCard[]> => {
      const [movies, screenings] = await Promise.all([this.api.getMovies(), this.api.getScreeningsOn(date)]);
      return movies
        .map((movie) => ({
          movie,
          screenings: screenings
            .filter((screening) => screening.movieId === movie.id)
            .sort((a, b) => a.time.localeCompare(b.time)),
        }))
        .filter((card) => card.screenings.length > 0);
    },
  });

  protected selectDay(iso: string): void {
    if (iso < today) {
      return;
    }
    this.router.navigate([], { queryParams: { date: iso } });
  }

  protected onDatePicked(date: Date | null): void {
    if (date) {
      this.selectDay(toIsoDate(date));
    }
  }

  protected openScreening(id: number): void {
    this.router.navigate(['/screenings', id, 'seats']);
  }
}

:host {
  display: block;
  max-width: 960px;
  margin: 0 auto;
  padding: 24px;
}

.day-picker {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-bottom: 24px;
}

.date-field {
  margin-left: 16px;
  width: 220px;
}

.movie-list {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.movie-card {
  border: 1px solid #d0d7de;
  border-radius: 8px;
  padding: 16px 20px;

  h2 {
    margin: 0 0 4px;
    font-size: 1.25rem;
  }
}

.movie-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin: 0 0 12px;
  color: #57606a;
}

.screenings {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.status {
  margin: 16px 0;
}

import { Routes } from '@angular/router';
import { MovieList } from './movie-list/movie-list';

export const appRoutes: Routes = [
  { path: '', pathMatch: 'full', component: MovieList },
  // Placeholders for screens 2-5, implemented by later tickets.
  { path: 'screenings/:id/seats', children: [] },
  { path: 'screenings/:id/summary', children: [] },
  { path: 'screenings/:id/checkout', children: [] },
  { path: 'confirmation', children: [] },
  { path: '**', redirectTo: '' },
];

import { ApplicationConfig, provideBrowserGlobalErrorListeners } from '@angular/core';
import { provideHttpClient } from '@angular/common/http';
import { provideNativeDateAdapter } from '@angular/material/core';
import { provideRouter, withComponentInputBinding } from '@angular/router';
import { appRoutes } from './app.routes';

export const appConfig: ApplicationConfig = {
  providers: [
    provideBrowserGlobalErrorListeners(),
    provideRouter(appRoutes, withComponentInputBinding()),
    provideHttpClient(),
    provideNativeDateAdapter(),
  ],
};

